using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.SqlClient;

using Microsoft.Extensions.Configuration;

namespace LaooMemoModule.Controllers;

[ApiController,Authorize,Route("api/company/memo/documents")]
public sealed class MemoDocumentController(IConfiguration config):MemoControllerBase(config)
{
 [HttpGet] public async Task<IActionResult> List(string? search=null,string? status=null,int page=1,int pageSize=20,CancellationToken ct=default){if(!Scope(out var company,out var user))return Forbid();await using var db=await Open(ct);if(!await Can(db,"50005","VIEW",ct))return Forbid();page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);const string tail=" FROM dbo.TDMEMemo m JOIN dbo.TDMEType t ON t.CompanyID=m.CompanyID AND t.MemoTypeID=m.MemoTypeID WHERE m.CompanyID=@company AND m.OwnerUserID=@user AND (@search IS NULL OR m.TemporaryNo LIKE N'%'+@search+N'%' OR m.MemoNo LIKE N'%'+@search+N'%' OR m.SubjectText LIKE N'%'+@search+N'%') AND (@status IS NULL OR m.StatusCode=@status)";var args=new(string,object?)[]{("@company",company),("@user",user),("@search",Clean(search)),("@status",Clean(status)?.ToUpperInvariant())};return Ok(new{items=await Query(db,"SELECT m.MemoID id,m.TemporaryNo temporaryNo,m.MemoNo memoNo,m.SubjectText subject,m.ToText recipient,m.MemoDate memoDate,m.ConfidentialityCode confidentiality,m.StatusCode status,t.TypeName typeName,m.CreateDate"+tail+" ORDER BY m.CreateDate DESC OFFSET @skip ROWS FETCH NEXT @take ROWS ONLY",ct,[..args,("@skip",(page-1)*pageSize),("@take",pageSize)]),total=await Scalar<int>(db,"SELECT COUNT(*)"+tail,ct,args),page,pageSize});}
 [HttpGet("{id:long}")] public async Task<IActionResult> Get(long id,CancellationToken ct){if(!Scope(out var company,out var user))return Forbid();await using var db=await Open(ct);if(!await CanRead(db,company,id,user,ct))return Forbid();var rows=await Query(db,"SELECT m.MemoID id,m.MemoTypeID typeId,m.TemporaryNo temporaryNo,m.MemoNo memoNo,m.SubjectText subject,m.ToText recipient,m.MemoDate memoDate,m.OwnerUserID ownerUserId,m.OwnerDepartmentID departmentId,m.ConfidentialityCode confidentiality,m.StatusCode status,m.CurrentVersionID versionId,v.VersionNo versionNo,v.BodyDeltaJson delta,v.BodyPlainText body FROM dbo.TDMEMemo m JOIN dbo.TDMEMemoVersion v ON v.VersionID=m.CurrentVersionID WHERE m.CompanyID=@company AND m.MemoID=@id",ct,("@company",company),("@id",id));if(rows.Count==0)return NotFound();var row=rows[0];row["recipients"]=await Query(db,"SELECT RecipientID id,RecipientRole role,SubjectType subjectType,SubjectID subjectId,ReadAt readAt FROM dbo.TDMEMemoRecipient WHERE CompanyID=@company AND MemoID=@id AND VersionID=@version",ct,("@company",company),("@id",id),("@version",row["versionId"]));row["approvals"]=await Query(db,"SELECT ApprovalID id,StepOrder stepOrder,StepName name,AssigneeUserID userId,StatusCode status,DecisionAt decisionAt,DecisionNote note FROM dbo.TDMEMemoApproval WHERE CompanyID=@company AND MemoID=@id AND VersionID=@version ORDER BY StepOrder",ct,("@company",company),("@id",id),("@version",row["versionId"]));row["attachments"]=await Query(db,"SELECT AttachmentID id,OriginalFileName fileName,ContentType contentType,FileSizeBytes sizeBytes,FileKind kind FROM dbo.TDMEAttachment WHERE CompanyID=@company AND MemoID=@id AND VersionID=@version ORDER BY CreateDate",ct,("@company",company),("@id",id),("@version",row["versionId"]));return Ok(row);}
 [HttpPost] public Task<IActionResult> Create(MemoRequest request,CancellationToken ct)=>Save(null,request,ct);
 [HttpPut("{id:long}")] public Task<IActionResult> Update(long id,MemoRequest request,CancellationToken ct)=>Save(id,request,ct);
 async Task<IActionResult> Save(long? id,MemoRequest request,CancellationToken ct){if(request.TypeId<=0||Clean(request.Subject) is null||Clean(request.Recipient) is null||Clean(request.Body) is null||request.Confidentiality is not("NORMAL" or "INTERNAL" or "SECRET"))return Invalid("ข้อมูล Memo ไม่ครบ","ระบุประเภท เรื่อง เรียน เนื้อหา และชั้นความลับ");if(!Scope(out var company,out var user))return Forbid();await using var db=await Open(ct);if(!await Can(db,"50005",id is null?"CREATE":"EDIT",ct))return Forbid();await using var tx=(SqlTransaction)await db.BeginTransactionAsync(ct);long memo,version;if(id is null){memo=await Scalar<long>(db,tx,"INSERT dbo.TDMEMemo(CompanyID,MemoTypeID,TemporaryNo,SubjectText,ToText,MemoDate,OwnerUserID,OwnerDepartmentID,ConfidentialityCode,StatusCode,CreateBy) OUTPUT INSERTED.MemoID VALUES(@company,@type,@temp,@subject,@recipient,@date,@user,@department,@secret,N'DRAFT',@user)",ct,("@company",company),("@type",request.TypeId),("@temp",$"TMP-{DateTime.UtcNow:yyyyMMddHHmmssfff}-{user}"),("@subject",request.Subject.Trim()),("@recipient",request.Recipient.Trim()),("@date",request.MemoDate.Date),("@user",user),("@department",request.DepartmentId),("@secret",request.Confidentiality));version=await Scalar<long>(db,tx,"INSERT dbo.TDMEMemoVersion(CompanyID,MemoID,VersionNo,BodyDeltaJson,BodyPlainText,CreateBy) OUTPUT INSERTED.VersionID VALUES(@company,@memo,1,@delta,@body,@user)",ct,("@company",company),("@memo",memo),("@delta",Clean(request.Delta)??"[{\"insert\":\"\\n\"}]"),("@body",request.Body.Trim()),("@user",user));await Execute(db,tx,"UPDATE dbo.TDMEMemo SET CurrentVersionID=@version WHERE CompanyID=@company AND MemoID=@memo",ct,("@version",version),("@company",company),("@memo",memo));}else{memo=id.Value;var current=await Query(db,tx,"SELECT CurrentVersionID versionId,StatusCode status,OwnerUserID owner FROM dbo.TDMEMemo WHERE CompanyID=@company AND MemoID=@memo",ct,("@company",company),("@memo",memo));if(current.Count==0){await tx.RollbackAsync(ct);return NotFound();}if(Convert.ToInt64(current[0]["owner"])!=user||Convert.ToString(current[0]["status"]) is not("DRAFT" or "RETURNED" or "WITHDRAWN")){await tx.RollbackAsync(ct);return Conflict(new{message="แก้ไข Memo ไม่ได้",description="แก้ไขได้เฉพาะเอกสารของตนที่เป็นร่าง ส่งกลับ หรือถอนแล้ว"});}version=Convert.ToInt64(current[0]["versionId"]);await Execute(db,tx,"UPDATE dbo.TDMEMemo SET MemoTypeID=@type,SubjectText=@subject,ToText=@recipient,MemoDate=@date,OwnerDepartmentID=@department,ConfidentialityCode=@secret,StatusCode=N'DRAFT',UpdateBy=@user,UpdateDate=SYSUTCDATETIME() WHERE CompanyID=@company AND MemoID=@memo;UPDATE dbo.TDMEMemoVersion SET BodyDeltaJson=@delta,BodyPlainText=@body,UpdateBy=@user,UpdateDate=SYSUTCDATETIME() WHERE CompanyID=@company AND VersionID=@version AND IsLocked=0",ct,("@type",request.TypeId),("@subject",request.Subject.Trim()),("@recipient",request.Recipient.Trim()),("@date",request.MemoDate.Date),("@department",request.DepartmentId),("@secret",request.Confidentiality),("@delta",Clean(request.Delta)??"[{\"insert\":\"\\n\"}]"),("@body",request.Body.Trim()),("@user",user),("@company",company),("@memo",memo),("@version",version));}
 await Execute(db,tx,"DELETE dbo.TDMEMemoRecipient WHERE CompanyID=@company AND MemoID=@memo AND VersionID=@version",ct,("@company",company),("@memo",memo),("@version",version));foreach(var recipient in request.Recipients?.Where(x=>x.SubjectId>0)??[]){var role=recipient.Role=="CC"?"CC":"TO";var type=recipient.SubjectType is "DEPARTMENT" or "ROLE"?recipient.SubjectType:"USER";await Execute(db,tx,"INSERT dbo.TDMEMemoRecipient(CompanyID,MemoID,VersionID,RecipientRole,SubjectType,SubjectID,CreateBy) VALUES(@company,@memo,@version,@role,@type,@subject,@user)",ct,("@company",company),("@memo",memo),("@version",version),("@role",role),("@type",type),("@subject",recipient.SubjectId),("@user",user));}await Audit(db,tx,company,memo,version,id is null?"CREATE":"EDIT",null,user,ct);await tx.CommitAsync(ct);return Ok(new{id=memo,versionId=version});}
 [HttpPost("{id:long}/revisions")] public async Task<IActionResult> CreateRevision(long id,CancellationToken ct){if(!Scope(out var company,out var user))return Forbid();await using var db=await Open(ct);if(!await Can(db,"50005","EDIT",ct))return Forbid();await using var tx=(SqlTransaction)await db.BeginTransactionAsync(ct);var source=await Query(db,tx,"SELECT m.CurrentVersionID versionId,v.BodyDeltaJson delta,v.BodyPlainText body FROM dbo.TDMEMemo m JOIN dbo.TDMEMemoVersion v ON v.CompanyID=m.CompanyID AND v.VersionID=m.CurrentVersionID WHERE m.CompanyID=@company AND m.MemoID=@id AND m.OwnerUserID=@user AND m.StatusCode IN(N'APPROVED',N'DISTRIBUTED') AND v.IsLocked=1",ct,("@company",company),("@id",id),("@user",user));if(source.Count==0){await tx.RollbackAsync(ct);return Conflict(new{message="สร้าง Version ไม่ได้",description="ต้องเป็น Memo ของตนที่อนุมัติแล้วและไม่มี Version ที่กำลังแก้ไข"});}var oldVersion=Convert.ToInt64(source[0]["versionId"]);var version=await Scalar<long>(db,tx,"INSERT dbo.TDMEMemoVersion(CompanyID,MemoID,VersionNo,BodyDeltaJson,BodyPlainText,CreateBy) OUTPUT INSERTED.VersionID VALUES(@company,@id,(SELECT ISNULL(MAX(VersionNo),0)+1 FROM dbo.TDMEMemoVersion WHERE CompanyID=@company AND MemoID=@id),@delta,@body,@user)",ct,("@company",company),("@id",id),("@delta",source[0]["delta"]),("@body",source[0]["body"]),("@user",user));await Execute(db,tx,"INSERT dbo.TDMEMemoRecipient(CompanyID,MemoID,VersionID,RecipientRole,SubjectType,SubjectID,CreateBy) SELECT CompanyID,MemoID,@newVersion,RecipientRole,SubjectType,SubjectID,@user FROM dbo.TDMEMemoRecipient WHERE CompanyID=@company AND MemoID=@id AND VersionID=@oldVersion;UPDATE dbo.TDMEMemo SET CurrentVersionID=@newVersion,StatusCode=N'DRAFT',ApprovedAt=NULL,DistributedAt=NULL,UpdateBy=@user,UpdateDate=SYSUTCDATETIME() WHERE CompanyID=@company AND MemoID=@id",ct,("@newVersion",version),("@oldVersion",oldVersion),("@user",user),("@company",company),("@id",id));await Audit(db,tx,company,id,version,"CREATE_VERSION",$"FromVersion={oldVersion}",user,ct);await tx.CommitAsync(ct);return Ok(new{id,versionId=version});}
 [HttpDelete("{id:long}")] public async Task<IActionResult> Delete(long id,CancellationToken ct){if(!Scope(out var company,out var user))return Forbid();await using var db=await Open(ct);if(!await Can(db,"50005","DELETE",ct))return Forbid();await using var tx=(SqlTransaction)await db.BeginTransactionAsync(ct);var valid=await Scalar<int>(db,tx,"SELECT COUNT(*) FROM dbo.TDMEMemo WHERE CompanyID=@company AND MemoID=@id AND OwnerUserID=@user AND StatusCode=N'DRAFT'",ct,("@company",company),("@id",id),("@user",user));if(valid==0){await tx.RollbackAsync(ct);return Conflict(new{message="ลบ Memo ไม่ได้",description="ลบได้เฉพาะ Memo ร่างของตน"});}await Execute(db,tx,"DELETE dbo.TDMEAudit WHERE CompanyID=@company AND MemoID=@id;DELETE dbo.TDMEAttachment WHERE CompanyID=@company AND MemoID=@id;DELETE dbo.TDMEMemoApproval WHERE CompanyID=@company AND MemoID=@id;DELETE dbo.TDMEMemoRecipient WHERE CompanyID=@company AND MemoID=@id;DELETE dbo.TDMEMemoVersion WHERE CompanyID=@company AND MemoID=@id;DELETE dbo.TDMEMemo WHERE CompanyID=@company AND MemoID=@id",ct,("@company",company),("@id",id));await tx.CommitAsync(ct);return NoContent();}
}
